<?php

// Loads a DataLife Engine installation for plugin tests (generated by
// dleplugin test). ROOT_DIR is the DLE copy of the test run; the plugin and its
// dependencies are connected to it like on a site.

global $config, $member_id, $is_loged, $is_logged, $db, $user_group, $cat_info;

error_reporting(E_ALL ^ E_WARNING ^ E_DEPRECATED ^ E_NOTICE);
ini_set("error_reporting", E_ALL ^ E_WARNING ^ E_DEPRECATED ^ E_NOTICE);

define("DATALIFEENGINE", true);
define("ROOT_DIR", dirname(__FILE__));
define("ENGINE_DIR", ROOT_DIR . "/engine");

/**
 * @return array<string, string>
 */
function load_dotenv()
{
    $data = @file_get_contents(ROOT_DIR . "/.env");
    $data = explode("\n", (string) $data);
    $data = array_map("trim", $data);
    $data = array_filter($data);
    return array_reduce(
        $data,
        /**
         * @param array<string, string> $a
         * @param string $b
         * @return array<string, string>
         */
        function ($a, $b) {
            $b = explode("=", $b, 2);
            if (count($b) != 2) {
                return $a;
            }
            $b[0] = trim($b[0]);
            $b[1] = trim($b[1], '" \'');
            if ($b[0]) {
                $a[$b[0]] = $b[1];
            }
            return $a;
        },
        []
    );
}

$_ENV = load_dotenv();

require_once ROOT_DIR . "/vendor/autoload.php";
require_once ENGINE_DIR . "/classes/plugins.class.php";

define("TEMPLATE_DIR", ROOT_DIR . "/templates/{$config["skin"]}");

date_default_timezone_set($config["date_adjust"]);

require_once DLEPlugins::Check(ENGINE_DIR . "/modules/functions.php");

require_once DLEPlugins::Check(
    ROOT_DIR . "/language/" . $config["langs"] . "/website.lng"
);

// DLE 19 replaced xfields.txt with xfields.json and the DLEXFields class.
// Plugins written for older versions still call the old functions; emulate
// them with the pre-19 row format: name, description, category, type,
// default (options of select fields).
if (!function_exists("xfieldsload")) {
    /**
     * @param bool $profile
     * @return array<int, array<int, string>>
     */
    function xfieldsload($profile = false)
    {
        if ($profile) {
            return [];
        }
        $data = json_decode((string) @file_get_contents(ENGINE_DIR . "/data/xfields.json"), true);
        $fields = [];
        foreach ($data["fields"] ?? [] as $name => $field) {
            $category = $field["category"] ?? "";
            $fields[] = [
                (string) ($field["name"] ?? $name),
                (string) ($field["description"] ?? ""),
                is_array($category) ? implode(",", $category) : (string) $category,
                (string) ($field["type"] ?? ""),
                str_replace("\r\n", "\n", (string) ($field["default"] ?? "")),
            ];
        }
        return $fields;
    }
}

if (!function_exists("xfieldsdataload")) {
    /**
     * @param string $id
     * @return array<string, string>
     */
    function xfieldsdataload($id)
    {
        require_once DLEPlugins::Check(ENGINE_DIR . "/classes/xfields.class.php");
        return DLEXFields::xfieldsdataload($id);
    }
}

dle_session();

// Keep driver selection separate from inclusion: DLE drivers load in the same
// scope as the rest of this bootstrap.
if (!function_exists("dleplugin_fastcache_class")) {
    function dleplugin_fastcache_class($cacheType): ?string
    {
        return $cacheType
            ? ENGINE_DIR . "/classes/" . ($cacheType == "2" ? "redis" : "memcache") . ".class.php"
            : null;
    }
}

// Read a table on a cache miss, preserving DLE's row keys and string decoding.
// Callers decide what counts as a miss for their particular cache.
if (!function_exists("dleplugin_load_table")) {
    function dleplugin_load_table(string $cacheName, string $table, string $order, ?callable $filter = null): array
    {
        global $db;

        $records = [];
        $db->query("SELECT * FROM {$table} ORDER BY {$order} ASC");
        while ($record = $db->get_row()) {
            if ($filter === null || $filter($record)) {
                $records[$record["id"]] = array_map("stripslashes", $record);
            }
        }
        set_vars($cacheName, $records);
        $db->free();

        return $records;
    }
}

$dlepluginCacheClass = dleplugin_fastcache_class($config["cache_type"]);
if ($dlepluginCacheClass !== null) {
    include_once DLEPlugins::Check($dlepluginCacheClass);
    $dlefastcache = new dle_fastcache($config);
}

// Let DLE restore a login before assigning the guest group.
$is_logged = false;
require_once DLEPlugins::Check(ENGINE_DIR . "/modules/sitelogin.php");
if (!$is_logged) {
    $member_id["user_group"] = 5;
}

// User groups treat all falsy cache values as misses; categories accept even
// an empty cached array.
$user_group = get_vars("usergroup") ?: dleplugin_load_table(
    "usergroup", USERPREFIX . "_usergroups", "id"
);
$cat_info = get_vars("category");
if (!is_array($cat_info)) {
    $cat_info = dleplugin_load_table(
        "category", PREFIX . "_category", "posi",
        static fn (array $category): bool => (bool) $category["active"]
    );
}

spl_autoload_register(function ($class) {
    if (strpos($class, "Tests\\") === 0) {
        $file = str_replace("\\", DIRECTORY_SEPARATOR, substr($class, 6));
        $path = ROOT_DIR . DIRECTORY_SEPARATOR . "tests" . DIRECTORY_SEPARATOR . $file . ".php";
        if (file_exists($path)) {
            require_once $path;
        }
    }
});

$confTestPath = ROOT_DIR . "/conftest.php";

if (file_exists($confTestPath)) {
    require_once $confTestPath;
}
